CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions ("tokenHash" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE ON UPDATE CASCADE, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX sessions_userId_idx ON sessions ("userId");
CREATE INDEX sessions_expiresAt_idx ON sessions ("expiresAt");
CREATE TABLE identity_imports (id TEXT PRIMARY KEY, "completedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
